BUG001.literal_setup:
// Start with an empty HugeGraph graph and no conflicting schema.
// The native traversal source for this graph is already bound to g.
def graph = g.getGraph()
def s = graph.schema()
long n = 30000L
long highCount = 4L * n
long firstUid = 680488L

['uid', 'id', 'key', 'expected_count', '_gsp_edge_ordinal'].each { name ->
    s.propertyKey(name).asLong().valueSingle().create()
}
s.propertyKey('mark').asBoolean().valueSingle().create()
s.vertexLabel('ScorRoot').useCustomizeStringId()
    .properties('uid', 'id', 'key', 'expected_count')
    .nullableKeys('uid', 'id', 'key', 'expected_count').create()
s.vertexLabel('ScorTarget').useCustomizeStringId()
    .properties('uid', 'mark', 'key')
    .nullableKeys('uid', 'mark', 'key').create()
['GSP_SC_HIGH', 'GSP_SC_REF'].each { name ->
    s.edgeLabel(name).link('ScorRoot', 'ScorTarget').multiTimes()
        .properties('_gsp_edge_ordinal').sortKeys('_gsp_edge_ordinal').create()
}
s.indexLabel('gsp_cost_lookup_ScorRoot_id')
    .onV('ScorRoot').by('id').secondary().create()

def root = g.addV('ScorRoot')
    .property(org.apache.tinkerpop.gremlin.structure.T.id, 'ScorRoot:1').next()
root.property('uid', 1L)
root.property('id', 1L)
root.property('key', 1L)
root.property('expected_count', highCount)
long written = 1L
for (long i = 0L; i < highCount; i++) {
    long uid = firstUid + i
    def v = g.addV('ScorTarget')
        .property(org.apache.tinkerpop.gremlin.structure.T.id, 'ScorTarget:' + uid).next()
    v.property('uid', uid)
    v.property('mark', true)
    v.property('key', 1L)
    if (++written % 250L == 0L) graph.tx().commit()
}
for (long uid = 2L; uid <= 4L; uid++) {
    def v = g.addV('ScorTarget')
        .property(org.apache.tinkerpop.gremlin.structure.T.id, 'ScorTarget:' + uid).next()
    v.property('uid', uid)
    v.property('mark', true)
    v.property('key', 1L)
    if (++written % 250L == 0L) graph.tx().commit()
}
graph.tx().commit()

written = 0L
for (long i = 0L; i < highCount; i++) {
    def a = g.V('ScorRoot:1').next()
    def b = g.V('ScorTarget:' + (firstUid + i)).next()
    a.addEdge('GSP_SC_HIGH', b, '_gsp_edge_ordinal', i)
    if (++written % 250L == 0L) graph.tx().commit()
}
for (long uid = 2L; uid <= 4L; uid++) {
    def a = g.V('ScorRoot:1').next()
    def b = g.V('ScorTarget:' + uid).next()
    a.addEdge('GSP_SC_REF', b, '_gsp_edge_ordinal', highCount + uid - 2L)
    if (++written % 250L == 0L) graph.tx().commit()
}
graph.tx().commit()

